async function renderComments(){const token=++state.request;main.innerHTML=heading('Hàng đợi bình luận','Theo dõi trạng thái và kiểm soát các nội dung sắp được gửi.',button('Hủy phần đang chờ','cancel-comments','stop','','danger')+button('Làm mới','reload-comments','refresh'))+info('Gửi lần lượt, cách nhau ít nhất 30 giây khi ứng dụng đang vận hành. “Cần kiểm tra” nghĩa là chưa xác định được kết quả; hãy xem trên Facebook trước khi thử lại.')+`<section class="panel" id="comments-results">${loading()}</section>`;const result=await rpc('comments',{ownerId:state.ownerId});if(token!==state.request)return;state.comments=result;$('#comments-results').innerHTML=result.items?.length?`<div class="table-wrap"><table><thead><tr><th>Nội dung bình luận</th><th>Bài viết</th><th>Trạng thái</th><th>Thời gian</th></tr></thead><tbody>${result.items.map(c=>`<tr><td class="text-wrap"><div>${escape(c.body)}</div>${c.error?`<small class="error-message">${escape(c.error)}</small>`:''}</td><td>#${c.group_id}<small class="muted"><br>${escape(c.post_id)}</small></td><td>${badge(...(commentLabels[c.state]||[c.state,'']))}</td><td>${escape(date(c.created_at))}</td></tr>`).join('')}</tbody></table></div><div class="panel-body"><span class="inline-muted">20 bình luận gần nhất</span></div>`:empty('Hàng đợi đang trống','Chọn bài viết và thêm nội dung hoặc link affiliate để tạo bình luận.','message',button('Xem bài viết','navigate','arrow','data-page="posts"'));}
